import React from "react";
import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import "./App.css";

// Сторінки
function Home() {
  return <h2>Головна сторінка</h2>;
}

function News() {
  return <h2>Сторінка новин</h2>;
}

function Sport() {
  return <h2>Сторінка спорту</h2>;
}

function Fashion() {
  return <h2>Сторінка моди</h2>;
}

function Subscriptions() {
  return <h2>Сторінка підписок</h2>;
}

function App() {
  return (
    <Router>
      <div className="container">
        <header className="header">
          <h1>Мій Журнал</h1>
          <nav>
            <Link to="/">Головна</Link>
            <Link to="/news">Новини</Link>
            <Link to="/sport">Спорт</Link>
            <Link to="/fashion">Мода</Link>
            <Link to="/subscriptions">Підписки</Link>
          </nav>
        </header>

        <main className="content">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/news" element={<News />} />
            <Route path="/sport" element={<Sport />} />
            <Route path="/fashion" element={<Fashion />} />
            <Route path="/subscriptions" element={<Subscriptions />} />
          </Routes>
        </main>

        <footer className="footer">
          <p>© 2025 Мій Журнал. Всі права захищено.</p>
        </footer>
      </div>
    </Router>
  );
}

export default App;
